import { test, expect } from '@playwright/test';

test.describe('Accessibility Tests', () => {
  test('should have accessible product images and login fields', async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('#username', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('input[data-test="submit"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('img.inventory_item_img')).toBeVisible();
    await expect(page.locator('img.inventory_item_img')).toHaveAttribute('alt');
  });

  test('should not have visible product images after logging out', async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('#username', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('input[data-test="submit"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('img.inventory_item_img')).toBeVisible();
    await expect(page.locator('img.inventory_item_img')).toHaveAttribute('alt');
    await page.click('a[data-test="logout"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('img.inventory_item_img')).toBeVisible();
    await expect(page.locator('img.inventory_item_img')).toHaveAttribute('alt');
  });
});
